public class ThreadLifecycleDemo {
    public static void main(String[] args) throws InterruptedException {
        Object lock = new Object();

        Thread worker = new Thread(() -> {
            synchronized (lock) {
                try {
                    // Transitions to TIMED_WAITING
                    Thread.sleep(500);
                    // Transitions to WAITING
                    lock.wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }, "Worker-Thread");

        System.out.println("State after creation: " + worker.getState()); // NEW
        worker.start();
        System.out.println("State after start(): " + worker.getState()); // RUNNABLE

        Thread.sleep(100);
        System.out.println("State during sleep(): " + worker.getState()); // TIMED_WAITING

        Thread.sleep(600);
        System.out.println("State during wait(): " + worker.getState()); // WAITING

        synchronized (lock) {
            lock.notify();
        }

        worker.join();
        System.out.println("State after completion: " + worker.getState()); // TERMINATED
    }
}
